// DecideWaiver implements the project-owned warranty_waiver.decide_waiver Handler.
func DecideWaiver(ctx context.Context, caps capabilities.DecideWaiverCapabilities, input capabilities.DecideWaiverInput) (capabilities.DecideWaiverOutput, error) {
	if caps.Execution == nil || caps.WarrantyWaiver == nil || caps.Notifications == nil {
		return capabilities.DecideWaiverOutput{}, &capabilities.BusinessError{Code: "warranty_waiver.decide_waiver.capability_unavailable"}
	}
	principal := caps.Execution.Principal()
	targetID := caps.Execution.TargetID()
	decision := string(input.Decision)
	if !principal.Known || principal.UserID == "" || targetID == "" || strings.TrimSpace(input.RequestKey) == "" || (decision != "approved" && decision != "rejected") {
		return capabilities.DecideWaiverOutput{}, &capabilities.BusinessError{Code: "warranty_waiver.decide_waiver.invalid_input"}
	}
	if decision == "rejected" && (input.Reason == nil || strings.TrimSpace(*input.Reason) == "") {
		return capabilities.DecideWaiverOutput{}, &capabilities.BusinessError{Code: "warranty_waiver.decide_waiver.rejection_reason_required"}
	}
	waiver, err := caps.WarrantyWaiver.GetForUpdate(ctx, targetID)
	if err != nil {
		return capabilities.DecideWaiverOutput{}, err
	}
	if waiver.Status != schema.WarrantyWaiverStatus("pending") {
		return capabilities.DecideWaiverOutput{}, &capabilities.BusinessError{Code: "warranty_waiver.decide_waiver.invalid_state"}
	}
	now := time.Now().UTC()
	mutation := data.NewWarrantyWaiverUpdate(waiver.ID).
		RequireStatusEqual(schema.WarrantyWaiverStatus("pending"), "warranty_waiver.decide_waiver.invalid_state").
		SetStatus(schema.WarrantyWaiverStatus(decision)).SetDecidedAt(now).
		SetDecidedByUserID(schema.NewWarrantyWaiverDecidedByUserIDReference(schema.IdentityUserID(principal.UserID))).
		WithExpectedUpdatedAt(waiver.UpdatedAt)
	if input.Reason != nil && strings.TrimSpace(*input.Reason) != "" {
		mutation = mutation.SetDecisionReason(strings.TrimSpace(*input.Reason))
	}
	updated, err := caps.WarrantyWaiver.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.DecideWaiverOutput{}, err
	}
	waiverID := string(waiver.ID)
	workOrderID := string(waiver.WorkOrderID.ID())
	_, err = caps.Notifications.Dispatch(ctx, capabilities.DecideWaiverNotificationIntent{
		EventType: "warranty_waiver.resolved", SourceEventID: "warranty_waiver.resolved:" + waiverID + ":" + decision,
		RecipientUserIDs: []string{string(waiver.AssignedUserID.ID())}, Surface: "business_workspace", SubjectObjectKey: "warranty_waiver",
		SubjectRecordID: waiverID, SubjectVersion: updated.UpdatedAt, DedupeKey: input.RequestKey, GroupKey: string(waiver.WorkOrderID.ID()), OccurredAt: now,
		Variables: []capabilities.DecideWaiverNotificationVariable{
			{Key: "outcome", StringValue: &decision},
			{Key: "work_order_id", StringValue: &workOrderID},
		},
	})
	if err != nil {
		return capabilities.DecideWaiverOutput{}, err
	}
	status := schema.WarrantyWaiverDecideWaiverStatusRejected
	if decision == "approved" {
		status = schema.WarrantyWaiverDecideWaiverStatusApproved
	}
	return capabilities.DecideWaiverOutput{Status: status, WaiverID: waiver.ID}, nil
}
package fieldservice

import (
	"fmt"
	"strconv"
	"strings"
)

// ParseMoney converts an exact two-decimal amount to minor units.
func ParseMoney(value string) (int64, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return 0, fmt.Errorf("amount is empty")
	}
	negative := strings.HasPrefix(value, "-")
	if negative {
		value = strings.TrimPrefix(value, "-")
	}
	parts := strings.Split(value, ".")
	if len(parts) > 2 || parts[0] == "" {
		return 0, fmt.Errorf("invalid amount")
	}
	fraction := "00"
	if len(parts) == 2 {
		if len(parts[1]) > 2 {
			return 0, fmt.Errorf("amount has more than two decimals")
		}
		fraction = parts[1] + strings.Repeat("0", 2-len(parts[1]))
	}
	major, err := strconv.ParseInt(parts[0], 10, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid amount: %w", err)
	}
	minor, err := strconv.ParseInt(fraction, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid amount: %w", err)
	}
	result := major*100 + minor
	if negative {
		result = -result
	}
	return result, nil
}

// FormatMoney renders minor units as an exact two-decimal amount.
func FormatMoney(minor int64) string {
	sign := ""
	if minor < 0 {
		sign = "-"
		minor = -minor
	}
	return fmt.Sprintf("%s%d.%02d", sign, minor/100, minor%100)
}

// MultiplyMoney multiplies an exact amount by a positive integer quantity.
func MultiplyMoney(value string, quantity int64) (string, error) {
	minor, err := ParseMoney(value)
	if err != nil {
		return "", err
	}
	if quantity <= 0 || (minor != 0 && quantity > (1<<63-1)/minor) {
		return "", fmt.Errorf("invalid quantity")
	}
	return FormatMoney(minor * quantity), nil
}

