func SubmitOrder(ctx context.Context, caps capabilities.SubmitOrderCapabilities, input capabilities.SubmitOrderInput) (capabilities.SubmitOrderOutput, error) {
	if caps.Execution == nil || caps.Device == nil || caps.WorkOrder == nil {
		return capabilities.SubmitOrderOutput{}, &capabilities.BusinessError{Code: "work_order.submit_order.capability_unavailable"}
	}
	principal := caps.Execution.Principal()
	if !principal.Known || principal.ActiveBusinessProfile == nil || principal.ActiveBusinessProfile.RecordID == "" {
		return capabilities.SubmitOrderOutput{}, &capabilities.BusinessError{Code: "work_order.submit_order.customer_profile_required"}
	}
	if input.DeviceID == "" || strings.TrimSpace(input.FaultDescription) == "" || input.PreferredVisitAt.IsZero() || strings.TrimSpace(input.RequestKey) == "" {
		return capabilities.SubmitOrderOutput{}, &capabilities.BusinessError{Code: "work_order.submit_order.invalid_input"}
	}
	device, err := caps.Device.Get(ctx, input.DeviceID)
	if err != nil {
		return capabilities.SubmitOrderOutput{}, err
	}
	customerID := schema.CustomerProfileID(principal.ActiveBusinessProfile.RecordID)
	if customerID == "" || device.CustomerID.ID() != customerID {
		return capabilities.SubmitOrderOutput{}, &capabilities.BusinessError{Code: "work_order.submit_order.device_not_owned"}
	}
	now := time.Now().UTC()
	order, err := caps.WorkOrder.Create(ctx, schema.CreateWorkOrder{
		CustomerID:       schema.NewWorkOrderCustomerIDReference(customerID),
		DeviceID:         schema.NewWorkOrderDeviceIDReference(device.ID),
		FaultDescription: strings.TrimSpace(input.FaultDescription),
		PreferredVisitAt: input.PreferredVisitAt.UTC(),
		Status:           schema.WorkOrderStatus("submitted"),
		SubmittedAt:      now,
	})
