// SendOverdueReminders implements the project-owned work_order.send_overdue_reminders Handler.
func SendOverdueReminders(ctx context.Context, caps capabilities.SendOverdueRemindersCapabilities, input capabilities.SendOverdueRemindersInput) (capabilities.SendOverdueRemindersOutput, error) {
	if caps.Execution == nil || caps.WorkOrder == nil || caps.ReminderReceipt == nil || caps.Notifications == nil {
		return capabilities.SendOverdueRemindersOutput{}, &capabilities.BusinessError{Code: "work_order.send_overdue_reminders.capability_unavailable"}
	}
	if strings.TrimSpace(input.RequestKey) == "" || input.RunAt.IsZero() {
		return capabilities.SendOverdueRemindersOutput{}, &capabilities.BusinessError{Code: "work_order.send_overdue_reminders.invalid_input"}
	}
	weekday := input.RunAt.Weekday()
	if weekday == time.Saturday || weekday == time.Sunday {
		return capabilities.SendOverdueRemindersOutput{ReminderCount: 0}, nil
	}
	cutoff := input.RunAt.UTC().Add(-48 * time.Hour)
	orders, err := caps.WorkOrder.List(ctx, data.NewWorkOrderQuery().
		WhereStatusEqual(schema.WorkOrderStatus("dispatched")).WhereDispatchedAtLessThanOrEqual(cutoff).
		OrderByIDAscending().Page(1, 200))
	if err != nil {
		return capabilities.SendOverdueRemindersOutput{}, err
	}
	location, err := time.LoadLocation("Asia/Shanghai")
	if err != nil {
		location = time.FixedZone("Asia/Shanghai", 8*60*60)
	}
	local := input.RunAt.In(location)
	businessDate := time.Date(local.Year(), local.Month(), local.Day(), 0, 0, 0, 0, location)
	candidates := make([]schema.WorkOrder, 0, len(orders))
	queries := make([]data.ReminderReceiptQuery, 0, len(orders))
	for _, order := range orders {
		if order.AssignedUserID == nil || order.DispatchedAt == nil {
			continue
		}
		dedupe := string(order.ID) + ":" + businessDate.Format("2006-01-02")
		candidates = append(candidates, order)
		queries = append(queries, data.NewReminderReceiptQuery().WhereDedupeKeyEqual(dedupe))
	}
	if len(candidates) == 0 {
		return capabilities.SendOverdueRemindersOutput{ReminderCount: 0}, nil
	}
	existing, err := caps.ReminderReceipt.ExistsBatch(ctx, queries)
	if err != nil {
		return capabilities.SendOverdueRemindersOutput{}, err
	}
	if len(existing) != len(candidates) {
		return capabilities.SendOverdueRemindersOutput{}, &capabilities.BusinessError{Code: "work_order.send_overdue_reminders.batch_mismatch"}
	}
	creates := make([]schema.CreateReminderReceipt, 0, len(candidates))
	intents := make([]capabilities.SendOverdueRemindersNotificationIntent, 0, len(candidates))
	for index, order := range candidates {
		if existing[index] {
			continue
		}
		dedupe := string(order.ID) + ":" + businessDate.Format("2006-01-02")
		userID := string(order.AssignedUserID.ID())
		orderID := string(order.ID)
		creates = append(creates, schema.CreateReminderReceipt{
			AssignedUserID: schema.NewReminderReceiptAssignedUserIDReference(schema.IdentityUserID(userID)), BusinessDate: businessDate,
			DedupeKey: dedupe, OwnerDepartmentID: order.OwnerDepartmentID, OwnerDepartmentPath: order.OwnerDepartmentPath,
			SentAt: input.RunAt.UTC(), WorkOrderID: schema.NewReminderReceiptWorkOrderIDReference(order.ID),
		})
		intents = append(intents, capabilities.SendOverdueRemindersNotificationIntent{
			EventType: "work_order.overdue", SourceEventID: "work_order.overdue:" + dedupe, RecipientUserIDs: []string{userID},
			Surface: "business_workspace", SubjectObjectKey: "work_order", SubjectRecordID: orderID, SubjectVersion: order.UpdatedAt,
			DedupeKey: dedupe, GroupKey: orderID, Alert: true, OccurredAt: input.RunAt.UTC(),
			Variables: []capabilities.SendOverdueRemindersNotificationVariable{{Key: "work_order_id", StringValue: &orderID}},
		})
	}
	if len(creates) == 0 {
		return capabilities.SendOverdueRemindersOutput{ReminderCount: 0}, nil
	}
	if _, err := caps.ReminderReceipt.CreateBatch(ctx, creates); err != nil {
		return capabilities.SendOverdueRemindersOutput{}, err
	}
	if _, err := caps.Notifications.DispatchBatch(ctx, intents); err != nil {
		return capabilities.SendOverdueRemindersOutput{}, err
	}
	return capabilities.SendOverdueRemindersOutput{ReminderCount: int64(len(creates))}, nil
}
